## `PerformanceSummaryCards.jsx`

```jsx
import React, { useMemo } from 'react';

/* ------------------------------------------------------------------ */
/* Bucketing                                                           */
/* ------------------------------------------------------------------ */

/**
 * Splits a month's days into High / Medium / Low revenue tiers using
 * quantile thresholds, then aggregates the sub-stats each card needs.
 *
 * @param {Array<{date:string, revenue:number, occupancy:number, roomsSold:number}>} days
 * @param {{ highQuantile?: number, lowQuantile?: number }} [options]
 */
export function buildPerformanceBuckets(days = [], options = {}) {
  const { highQuantile = 0.67, lowQuantile = 0.33 } = options;

  // Only days with actual data participate — blank leading/trailing
  // calendar cells and future days would skew the thresholds.
  const active = days.filter(
    (d) => d && Number.isFinite(d.revenue) && d.revenue > 0
  );

  const quantile = (sorted, q) => {
    if (!sorted.length) return 0;
    const pos = (sorted.length - 1) * q;
    const lo = Math.floor(pos);
    const hi = Math.ceil(pos);
    return sorted[lo] + (sorted[hi] - sorted[lo]) * (pos - lo);
  };

  const revenues = active.map((d) => d.revenue).sort((a, b) => a - b);
  const highCut = quantile(revenues, highQuantile);
  const lowCut = quantile(revenues, lowQuantile);

  const tierFor = (revenue) => {
    if (revenue >= highCut) return 'high';
    if (revenue <= lowCut) return 'low';
    return 'medium';
  };

  const empty = () => ({ days: [] });
  const groups = { high: empty(), medium: empty(), low: empty() };
  active.forEach((d) => groups[tierFor(d.revenue)].days.push(d));

  const aggregate = (bucket) => {
    const n = bucket.days.length;
    const sum = (key) => bucket.days.reduce((t, d) => t + (d[key] || 0), 0);
    return {
      dayCount: n,
      avgRevenue: n ? sum('revenue') / n : 0,
      avgOccupancy: n ? sum('occupancy') / n : 0,
      totalRoomsSold: sum('roomsSold'),
      totalRevenue: sum('revenue'),
      dates: bucket.days.map((d) => d.date),
    };
  };

  return {
    high: aggregate(groups.high),
    medium: aggregate(groups.medium),
    low: aggregate(groups.low),
    thresholds: { highCut, lowCut },
  };
}

/* ------------------------------------------------------------------ */
/* Formatters                                                          */
/* ------------------------------------------------------------------ */

const currency = new Intl.NumberFormat('en-US', {
  style: 'currency',
  currency: 'USD',
  maximumFractionDigits: 0,
});
const compactInt = new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 });

const fmtRevenue = (v) => (Number.isFinite(v) ? currency.format(v) : '—');
const fmtPct = (v) => (Number.isFinite(v) ? `${v.toFixed(1)}%` : '—');
const fmtInt = (v) => (Number.isFinite(v) ? compactInt.format(v) : '—');

/* ------------------------------------------------------------------ */
/* Tier theming                                                        */
/* ------------------------------------------------------------------ */

const TIERS = {
  high: {
    key: 'high',
    label: 'High',
    title: 'High Revenue Days',
    caption: 'Peak demand — hold rate, protect inventory',
    // Card face: light gradient so the top edge reads as the lit side.
    face: 'bg-gradient-to-b from-emerald-50 via-white to-emerald-50/70',
    ring: 'ring-emerald-900/10',
    // Beveled outer border: light top-left, dark bottom-right.
    bevel: 'bg-gradient-to-br from-emerald-200/90 via-emerald-400/60 to-emerald-700/70',
    rail: 'bg-gradient-to-b from-emerald-300 via-emerald-500 to-emerald-700',
    lift:
      'shadow-[inset_0_1px_0_rgba(255,255,255,0.95),' +
      'inset_0_-3px_6px_rgba(6,78,59,0.10),' +
      '0_12px_24px_-10px_rgba(6,95,70,0.45),' +
      '0_2px_4px_rgba(15,23,42,0.10)]',
    liftHover:
      'hover:shadow-[inset_0_1px_0_rgba(255,255,255,0.95),' +
      'inset_0_-3px_6px_rgba(6,78,59,0.10),' +
      '0_18px_32px_-12px_rgba(6,95,70,0.50),' +
      '0_3px_6px_rgba(15,23,42,0.12)]',
    pill: 'bg-gradient-to-b from-emerald-400 to-emerald-600 text-white',
    pillRing: 'ring-emerald-800/40',
    well: 'bg-emerald-50/80 ring-emerald-900/[0.07]',
    wellLabel: 'text-emerald-800/70',
    wellValue: 'text-emerald-950',
    heading: 'text-emerald-950',
    subheading: 'text-emerald-800/70',
    focus: 'focus-visible:outline-emerald-600',
  },
  medium: {
    key: 'medium',
    label: 'Medium',
    title: 'Medium Revenue Days',
    caption: 'Steady demand — tune length-of-stay controls',
    face: 'bg-gradient-to-b from-amber-50 via-white to-amber-50/70',
    ring: 'ring-amber-900/10',
    bevel: 'bg-gradient-to-br from-amber-200/90 via-amber-400/60 to-amber-700/70',
    rail: 'bg-gradient-to-b from-amber-300 via-amber-500 to-amber-700',
    lift:
      'shadow-[inset_0_1px_0_rgba(255,255,255,0.95),' +
      'inset_0_-3px_6px_rgba(120,53,15,0.10),' +
      '0_12px_24px_-10px_rgba(146,64,14,0.45),' +
      '0_2px_4px_rgba(15,23,42,0.10)]',
    liftHover:
      'hover:shadow-[inset_0_1px_0_rgba(255,255,255,0.95),' +
      'inset_0_-3px_6px_rgba(120,53,15,0.10),' +
      '0_18px_32px_-12px_rgba(146,64,14,0.50),' +
      '0_3px_6px_rgba(15,23,42,0.12)]',
    pill: 'bg-gradient-to-b from-amber-400 to-amber-600 text-amber-950',
    pillRing: 'ring-amber-800/40',
    well: 'bg-amber-50/80 ring-amber-900/[0.07]',
    wellLabel: 'text-amber-800/70',
    wellValue: 'text-amber-950',
    heading: 'text-amber-950',
    subheading: 'text-amber-800/70',
    focus: 'focus-visible:outline-amber-600',
  },
  low: {
    key: 'low',
    label: 'Low',
    title: 'Low Revenue Days',
    caption: 'Soft demand — stimulate with targeted offers',
    face: 'bg-gradient-to-b from-indigo-50 via-white to-indigo-50/70',
    ring: 'ring-indigo-900/10',
    bevel: 'bg-gradient-to-br from-indigo-200/90 via-indigo-400/60 to-indigo-700/70',
    rail: 'bg-gradient-to-b from-indigo-300 via-indigo-500 to-indigo-700',
    lift:
      'shadow-[inset_0_1px_0_rgba(255,255,255,0.95),' +
      'inset_0_-3px_6px_rgba(30,27,75,0.10),' +
      '0_12px_24px_-10px_rgba(55,48,163,0.45),' +
      '0_2px_4px_rgba(15,23,42,0.10)]',
    liftHover:
      'hover:shadow-[inset_0_1px_0_rgba(255,255,255,0.95),' +
      'inset_0_-3px_6px_rgba(30,27,75,0.10),' +
      '0_18px_32px_-12px_rgba(55,48,163,0.50),' +
      '0_3px_6px_rgba(15,23,42,0.12)]',
    pill: 'bg-gradient-to-b from-indigo-400 to-indigo-600 text-white',
    pillRing: 'ring-indigo-900/40',
    well: 'bg-indigo-50/80 ring-indigo-900/[0.07]',
    wellLabel: 'text-indigo-800/70',
    wellValue: 'text-indigo-950',
    heading: 'text-indigo-950',
    subheading: 'text-indigo-800/70',
    focus: 'focus-visible:outline-indigo-600',
  },
};

const TIER_ORDER = ['high', 'medium', 'low'];

/* Shared shadow recipes ------------------------------------------------ */

// Recessed well: shadow falls from the top edge inward, plus a light
// bottom lip, so the panel reads as carved into the card face.
const WELL_DEPTH =
  'shadow-[inset_0_2px_4px_rgba(15,23,42,0.10),' +
  'inset_0_-1px_0_rgba(255,255,255,0.85)]';

// Micro-emboss: 1px specular top edge, 1px occlusion underneath,
// and a tight contact shadow. Deliberately subtle at pill scale.
const PILL_EMBOSS =
  'shadow-[inset_0_1px_0_rgba(255,255,255,0.55),' +
  'inset_0_-1px_1px_rgba(15,23,42,0.22),' +
  '0_1px_2px_rgba(15,23,42,0.18)]';

/* ------------------------------------------------------------------ */
/* Pieces                                                              */
/* ------------------------------------------------------------------ */

function TierPill({ tier }) {
  return (
    <span
      className={[
        'inline-flex shrink-0 items-center gap-1.5 rounded-full',
        'px-2.5 py-1 text-[0.6875rem] font-semibold uppercase leading-none tracking-[0.08em]',
        'ring-1',
        tier.pill,
        tier.pillRing,
        PILL_EMBOSS,
      ].join(' ')}
    >
      <span
        aria-hidden="true"
        className="h-1.5 w-1.5 rounded-full bg-white/85 shadow-[inset_0_-1px_1px_rgba(15,23,42,0.25)]"
      />
      {tier.label}
    </span>
  );
}

function StatWell({ tier, label, value, hint }) {
  return (
    <div
      className={[
        'rounded-xl px-3 py-2.5 ring-1',
        tier.well,
        WELL_DEPTH,
      ].join(' ')}
    >
      <dt
        className={[
          'text-[0.625rem] font-semibold uppercase tracking-[0.07em]',
          tier.wellLabel,
        ].join(' ')}
      >
        {label}
      </dt>
      <dd
        className={[
          'mt-1 font-semibold tabular-nums leading-tight',
          'text-[0.9375rem] sm:text-base',
          tier.wellValue,
        ].join(' ')}
      >
        {value}
      </dd>
      {hint ? (
        <p className={['mt-0.5 text-[0.625rem] leading-tight', tier.wellLabel].join(' ')}>
          {hint}
        </p>
      ) : null}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Card                                                                */
/* ------------------------------------------------------------------ */

function PerformanceSummaryCard({ tier, stats, totalActiveDays, onSelect }) {
  const share =
    totalActiveDays > 0 ? (stats.dayCount / totalActiveDays) * 100 : 0;

  const interactive = typeof onSelect === 'function';
  const Face = interactive ? 'button' : 'div';

  return (
    // Outer layer is the bevel: a 1.5px gradient frame that is light at the
    // top-left and dark at the bottom-right, simulating a single light source.
    <div
      className={[
        'group rounded-2xl p-[1.5px]',
        tier.bevel,
        'transition-transform duration-200 ease-out',
        interactive ? 'hover:-translate-y-0.5 active:translate-y-px' : '',
      ].join(' ')}
    >
      <Face
        type={interactive ? 'button' : undefined}
        onClick={interactive ? () => onSelect(tier.key, stats) : undefined}
        aria-label={
          interactive
            ? `${tier.title}: ${stats.dayCount} days, ${fmtRevenue(
                stats.avgRevenue
              )} average revenue. Filter calendar to these days.`
            : undefined
        }
        className={[
          'relative w-full overflow-hidden rounded-[calc(1rem-1px)] text-left',
          'px-4 pb-4 pt-3.5 sm:px-5 sm:pb-5',
          tier.face,
          'ring-1',
          tier.ring,
          tier.lift,
          tier.liftHover,
          'transition-shadow duration-200 ease-out',
          'focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2',
          tier.focus,
        ].join(' ')}
      >
        {/* Beveled accent rail on the leading edge */}
        <span
          aria-hidden="true"
          className={[
            'pointer-events-none absolute inset-y-3 left-0 w-1 rounded-r-full',
            tier.rail,
            'shadow-[inset_0_1px_0_rgba(255,255,255,0.7),1px_0_2px_rgba(15,23,42,0.18)]',
          ].join(' ')}
        />

        {/* Specular sheen across the upper face */}
        <span
          aria-hidden="true"
          className="pointer-events-none absolute inset-x-0 top-0 h-16 bg-gradient-to-b from-white/70 to-transparent"
        />

        <div className="relative pl-2.5">
          {/* Header */}
          <div className="flex items-start justify-between gap-3">
            <div className="min-w-0">
              <h3
                className={[
                  'truncate text-sm font-semibold tracking-tight sm:text-[0.9375rem]',
                  tier.heading,
                ].join(' ')}
              >
                {tier.title}
              </h3>
              <p className={['mt-0.5 text-[0.6875rem] leading-snug', tier.subheading].join(' ')}>
                {tier.caption}
              </p>
            </div>
            <TierPill tier={tier} />
          </div>

          {/* Sub-stat wells */}
          <dl className="mt-3.5 grid grid-cols-2 gap-2 sm:gap-2.5">
            <StatWell
              tier={tier}
              label="Day Count"
              value={fmtInt(stats.dayCount)}
              hint={
                totalActiveDays > 0
                  ? `${share.toFixed(0)}% of month`
                  : undefined
              }
            />
            <StatWell
              tier={tier}
              label="Avg Revenue"
              value={fmtRevenue(stats.avgRevenue)}
              hint="per day"
            />
            <StatWell
              tier={tier}
              label="Avg Occupancy"
              value={fmtPct(stats.avgOccupancy)}
            />
            <StatWell
              tier={tier}
              label="Total Rooms Sold"
              value={fmtInt(stats.totalRoomsSold)}
            />
          </dl>
        </div>
      </Face>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Group                                                               */
/* ------------------------------------------------------------------ */

/**
 * Renders the High / Medium / Low performance summary row.
 *
 * Pass either `buckets` (output of buildPerformanceBuckets) or raw `days`.
 */
export default function PerformanceSummaryCards({
  days,
  buckets: bucketsProp,
  onSelectTier,
  className = '',
}) {
  const buckets = useMemo(
    () => bucketsProp ?? buildPerformanceBuckets(days),
    [bucketsProp, days]
  );

  const totalActiveDays = TIER_ORDER.reduce(
    (t, key) => t + (buckets[key]?.dayCount || 0),
    0
  );

  return (
    <section
      aria-label="Revenue performance summary by day tier"
      className={['grid gap-3 sm:gap-4 lg:grid-cols-3', className].join(' ')}
    >
      {TIER_ORDER.map((key) => (
        <PerformanceSummaryCard
          key={key}
          tier={TIERS[key]}
          stats={buckets[key] ?? {
            dayCount: 0,
            avgRevenue: 0,
            avgOccupancy: 0,
            totalRoomsSold: 0,
          }}
          totalActiveDays={totalActiveDays}
          onSelect={onSelectTier}
        />
      ))}
    </section>
  );
}
```

## Wiring into `MonthlyCalendar.jsx`

```jsx
import PerformanceSummaryCards, {
  buildPerformanceBuckets,
} from './PerformanceSummaryCards';

// inside MonthlyCalendar
const buckets = useMemo(() => buildPerformanceBuckets(monthDays), [monthDays]);

// Reuse the same thresholds for per-day cell tinting so the cards and the
// grid never disagree about which day is "High".
const tierByDate = useMemo(() => {
  const map = new Map();
  ['high', 'medium', 'low'].forEach((tier) =>
    buckets[tier].dates.forEach((d) => map.set(d, tier))
  );
  return map;
}, [buckets]);

return (
  <div className="space-y-5">
    <PerformanceSummaryCards
      buckets={buckets}
      onSelectTier={(tier) => setActiveTierFilter((cur) => (cur === tier ? null : tier))}
    />
    {/* existing calendar grid, reading tierByDate.get(day.date) */}
  </div>
);
```

Notes on the implementation choices:

The depth effect is built from three stacked layers rather than a single `box-shadow`, which is what makes it read as tactile at small sizes: a 1.5px gradient frame for the bevel (light top-left → dark bottom-right), a 1px inset white highlight on the card face for the lit top edge, and a colored ambient drop shadow tinted to each tier's hue instead of neutral black. The stat wells invert that logic — inset shadow from the top, light lip at the bottom — so they recede against the raised face.

Lighting is consistent across all three tiers (single source, upper-left), so the cards sit together as a set. The `onSelectTier` prop is optional; when supplied, cards render as `<button>` with proper labels and focus rings, otherwise as plain `<div>` so you don't ship non-interactive buttons to screen readers.

Bucketing uses quantiles rather than fixed dollar thresholds so the tiers stay meaningful across seasons, and days with zero revenue are excluded so blank calendar cells don't drag the thresholds down. If you'd rather anchor to budget or last-year actuals, swap the `quantile` calls in `buildPerformanceBuckets` — the card layer doesn't care how tiers are derived.

