## 1 + 2. Daily Detail Modal with embossed metric tiles

```tsx
// components/calendar/DailyDetailModal.tsx
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription,
} from "@/components/ui/dialog";
import { DollarSign, BedDouble, Tag, TrendingUp } from "lucide-react";
import type { LucideIcon } from "lucide-react";

type Metric = {
  label: string;
  value: string;
  delta?: string;
  trend?: "up" | "down";
  icon: LucideIcon;
  glow: string; // tailwind color for the ambient glow
};

const EMBOSS =
  "shadow-[inset_0_1px_0_0_rgba(255,255,255,0.10),inset_0_-1px_0_0_rgba(0,0,0,0.55),0_10px_24px_-12px_rgba(0,0,0,0.9)]";

function MetricTile({ label, value, delta, trend, icon: Icon, glow }: Metric) {
  return (
    <div
      className={`group relative overflow-hidden rounded-xl border border-slate-700/60
                  bg-gradient-to-b from-slate-800/90 to-slate-900/95 p-4
                  ${EMBOSS} transition-all duration-300
                  hover:border-slate-600/80 hover:-translate-y-0.5`}
    >
      {/* subtle gradient glow */}
      <div
        aria-hidden
        className={`pointer-events-none absolute -right-8 -top-10 h-24 w-24 rounded-full
                    ${glow} opacity-20 blur-2xl transition-opacity duration-300
                    group-hover:opacity-35`}
      />
      {/* top bevel highlight */}
      <div
        aria-hidden
        className="pointer-events-none absolute inset-x-0 top-0 h-px
                   bg-gradient-to-r from-transparent via-white/25 to-transparent"
      />

      <div className="relative flex items-center justify-between">
        <span className="text-[11px] font-medium uppercase tracking-wider text-slate-400">
          {label}
        </span>
        <span className="rounded-md bg-slate-950/60 p-1.5 ring-1 ring-inset ring-white/10">
          <Icon className="h-3.5 w-3.5 text-slate-300" aria-hidden />
        </span>
      </div>

      <p className="relative mt-2 text-2xl font-semibold tabular-nums text-slate-50
                    [text-shadow:0_1px_1px_rgba(0,0,0,0.6)]">
        {value}
      </p>

      {delta && (
        <p
          className={`relative mt-1 text-xs font-medium tabular-nums ${
            trend === "down" ? "text-rose-400" : "text-emerald-400"
          }`}
        >
          {trend === "down" ? "▼" : "▲"} {delta}
          <span className="ml-1 text-slate-500">vs. LY</span>
        </p>
      )}
    </div>
  );
}

export function DailyDetailModal({
  open, onOpenChange, date, metrics, children,
}: {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  date: Date;
  metrics: { revenue: string; occupancy: string; adr: string; revpar: string };
  children?: React.ReactNode; // event list, notes, etc.
}) {
  const tiles: Metric[] = [
    { label: "Revenue",   value: metrics.revenue,   delta: "8.4%",  trend: "up",   icon: DollarSign, glow: "bg-emerald-500" },
    { label: "Occupancy", value: metrics.occupancy, delta: "2.1%",  trend: "up",   icon: BedDouble,  glow: "bg-sky-500" },
    { label: "ADR",       value: metrics.adr,       delta: "1.3%",  trend: "down", icon: Tag,        glow: "bg-violet-500" },
    { label: "RevPAR",    value: metrics.revpar,    delta: "5.9%",  trend: "up",   icon: TrendingUp, glow: "bg-amber-500" },
  ];

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        className="max-w-2xl gap-0 rounded-2xl border border-slate-700/80
                   bg-slate-900/95 p-0 text-slate-100 shadow-2xl backdrop-blur-xl
                   data-[state=open]:duration-200"
      >
        {/* outer bevel: inner top highlight + deep drop */}
        <div className="pointer-events-none absolute inset-0 rounded-2xl
                        shadow-[inset_0_1px_0_0_rgba(255,255,255,0.08)]" />

        <DialogHeader className="space-y-1 border-b border-slate-700/60 px-6 py-5">
          <DialogTitle className="text-lg font-semibold tracking-tight text-slate-50">
            {date.toLocaleDateString(undefined, {
              weekday: "long", month: "long", day: "numeric", year: "numeric",
            })}
          </DialogTitle>
          <DialogDescription className="text-sm text-slate-400">
            Daily performance summary and scheduled events.
          </DialogDescription>
        </DialogHeader>

        <div className="grid grid-cols-2 gap-3 px-6 py-5 sm:grid-cols-4">
          {tiles.map((t) => (
            <MetricTile key={t.label} {...t} />
          ))}
        </div>

        {children && (
          <div className="max-h-72 overflow-y-auto border-t border-slate-700/60 px-6 py-4">
            {children}
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}
