## 3. Event popup — beveled card + type badge

```tsx
// components/calendar/EventPopupModal.tsx
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { CalendarClock, MapPin } from "lucide-react";

type EventType = "holiday" | "conference" | "blackout" | "promotion" | "local";

const BADGE: Record<EventType, string> = {
  holiday:    "bg-emerald-500/15 text-emerald-300 ring-emerald-400/30",
  conference: "bg-sky-500/15 text-sky-300 ring-sky-400/30",
  blackout:   "bg-rose-500/15 text-rose-300 ring-rose-400/30",
  promotion:  "bg-amber-500/15 text-amber-300 ring-amber-400/30",
  local:      "bg-violet-500/15 text-violet-300 ring-violet-400/30",
};

export function EventPopupModal({
  open, onOpenChange, event,
}: {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  event: { title: string; type: EventType; timeRange: string; venue?: string; notes?: string };
}) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        className="max-w-md rounded-2xl border border-slate-700/80
                   bg-gradient-to-b from-slate-800/95 to-slate-900/95
                   p-6 text-slate-100 backdrop-blur-xl
                   shadow-[inset_0_1px_0_0_rgba(255,255,255,0.10),inset_0_-1px_0_0_rgba(0,0,0,0.6),0_24px_48px_-16px_rgba(0,0,0,0.85)]"
      >
        <DialogHeader className="space-y-2 text-left">
          <span
            className={`inline-flex w-fit items-center gap-1.5 rounded-full px-2.5 py-0.5
                        text-[11px] font-semibold uppercase tracking-wide
                        ring-1 ring-inset ${BADGE[event.type]}`}
          >
            <span className="h-1.5 w-1.5 rounded-full bg-current" aria-hidden />
            {event.type}
